verus! {

    /// Returns an index `min_i` in the half-open interval `[s, e)` such that
    /// `a[min_i]` is the minimum value among `a[s]`, `a[s+1]`, …, `a[e-1]`.
    ///
    /// Requires:
    ///   0 < a.len(),
    ///   s < e,
    ///   e <= a.len()
    ///
    /// Ensures:
    ///   s <= result < e
    ///   For all k in [s, e), a[result] <= a[k].
    ///
    /// Time-complexity: O(e-s).  Terminates because we decrease `e - i` on each loop step.
    fn find_min_index(a: &[int], s: usize, e: usize) -> usize
        requires
            a.len() > 0,
            s < e,
            e <= a.len(),
        ensures
            // result lives in [s, e)
            s <= result && result < e,
        ensures
            // result really points at a minimum in [s, e)
            forall |k: usize| s <= k && k < e ==> a[result] <= a[k],
        decreases
            // to show the while‐loop below terminates
            e - s
    {
        // We maintain `min_i` = index of minimal element seen so far in [s .. i)
        let mut min_i: usize = s;
        // We will scan i from s+1 up to e
        let mut i: usize = s + 1;

        while i < e
            invariant
                // Invariant 1: pointers stay in range
                s <= min_i && min_i < e,
            invariant
                s < i && i <= e,
            invariant
                // Invariant 2: up to i (exclusive), `min_i` is truly the argmin
                forall |k: usize| s <= k && k < i ==> a[min_i] <= a[k],
            decreases
                // each iteration increases i, so (e - i) strictly decreases
                e - i
        {
            if a[i] < a[min_i] {
                min_i = i;
            }
            i += 1;
        }

        // After the loop, i == e and min_i still denotes
        // the index of a minimum in [s, e).
        min_i
    }

}